import{b as i,O as t,g as a,j as e}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"附录 D：常见坑与排错","description":"","frontmatter":{},"headers":[],"relativePath":"automation/pytest/appendix/pitfalls/index.md","filePath":"自动化测试/2.pytest+requests/6.附录/D.常见坑与排错.md","lastUpdated":1789573585000}'),n={name:"automation/pytest/appendix/pitfalls/index.md"};function o(l,s,h,r,p,d){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="附录-d-常见坑与排错" tabindex="-1">附录 D：常见坑与排错 <a class="header-anchor" href="#附录-d-常见坑与排错" aria-label="Permalink to &quot;附录 D：常见坑与排错&quot;">​</a></h1><blockquote><p>把接口测试里最常踩的坑和报错集中在这里，配好排查思路。遇到问题先查这里，再上搜索引擎。</p></blockquote><h2 id="坑-1-测试没被收集-0-个测试" tabindex="-1">坑 1：测试没被收集（0 个测试） <a class="header-anchor" href="#坑-1-测试没被收集-0-个测试" aria-label="Permalink to &quot;坑 1：测试没被收集（0 个测试）&quot;">​</a></h2><p><strong>症状</strong>：<code>pytest</code> 跑了，输出 <code>no tests ran</code> 或 <code>collected 0 items</code>。</p><p><strong>原因排查</strong>：</p><ol><li>文件名不对——必须是 <code>test_*.py</code> 或 <code>*_test.py</code></li><li>函数名不对——必须是 <code>test_*</code> 开头</li><li>测试在 <code>testpaths</code> 之外，或目录被 <code>norecursedirs</code> 排除了</li><li>忘了 <code>import pytest</code>（写 <code>@pytest.fixture</code> 会 NameError，但写 <code>@pytest.mark.parametrize</code> 会直接静默失效）</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --collect-only</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 看 pytest 到底收集到了什么</span></span></code></pre></div><h2 id="坑-2-fixture-找不到" tabindex="-1">坑 2：fixture 找不到 <a class="header-anchor" href="#坑-2-fixture-找不到" aria-label="Permalink to &quot;坑 2：fixture 找不到&quot;">​</a></h2><p><strong>症状</strong>：<code>fixture &#39;client&#39; not found</code>。</p><p><strong>原因排查</strong>：</p><ol><li>fixture 定义在<strong>另一个文件</strong>里，没放到 <code>conftest.py</code>（测试文件里的 fixture 只对本文件可见）</li><li><code>conftest.py</code> 放的位置不对——只在它的目录及子目录可见</li><li>fixture 名拼写错误</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fixtures</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 列出当前可见的所有 fixture</span></span></code></pre></div><h2 id="坑-3-改了代码测试没变" tabindex="-1">坑 3：改了代码测试没变 <a class="header-anchor" href="#坑-3-改了代码测试没变" aria-label="Permalink to &quot;坑 3：改了代码测试没变&quot;">​</a></h2><p><strong>症状</strong>：改了源码，测试还是老结果。</p><p><strong>原因</strong>：</p><ul><li>Python 缓存了旧模块（<code>.pyc</code>），或测试进程没重新加载</li><li>用 <code>--lf</code> 时只跑了「上次失败的」，改的代码不在那批里</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;__pycache__&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 清 pyc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cache-clear</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 清 pytest 缓存（--lf 状态）</span></span></code></pre></div><h2 id="坑-4-session-级-fixture-每个测试都重新跑" tabindex="-1">坑 4：session 级 fixture 每个测试都重新跑 <a class="header-anchor" href="#坑-4-session-级-fixture-每个测试都重新跑" aria-label="Permalink to &quot;坑 4：session 级 fixture 每个测试都重新跑&quot;">​</a></h2><p><strong>症状</strong>：<code>scope=&quot;session&quot;</code> 的 fixture 看起来每个测试都在执行（登录了 N 次）。</p><p><strong>原因</strong>：用了 <code>pytest -n</code>（xdist 并行），每个 worker 进程各执行一次 session fixture。这是<strong>正常现象</strong>，不是 bug。</p><p><strong>解决</strong>：确认 fixture 逻辑是否有「全局唯一」副作用（如重置数据库），有的话改用串行或 <code>--dist=loadscope</code>。</p><h2 id="坑-5-请求超时-连接被拒" tabindex="-1">坑 5：请求超时 / 连接被拒 <a class="header-anchor" href="#坑-5-请求超时-连接被拒" aria-label="Permalink to &quot;坑 5：请求超时 / 连接被拒&quot;">​</a></h2><p><strong>症状</strong>：<code>requests.exceptions.ConnectionError</code> 或 <code>Timeout</code>。</p><p><strong>排查思路</strong>：</p><ol><li><code>BASE_URL</code> 对不对（多了 <code>/</code> 会 404，少了会连不上）</li><li>服务是不是没起来（先手动 <code>curl</code> 一下）</li><li>有没有设 <code>timeout</code>（第 14 章：不设会无限等）</li><li>代理/VPN 是否拦截了请求</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3001/api/health</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 手动验证服务通不通（无需登录）</span></span></code></pre></div><h2 id="坑-6-登录后接口还是-401" tabindex="-1">坑 6：登录后接口还是 401 <a class="header-anchor" href="#坑-6-登录后接口还是-401" aria-label="Permalink to &quot;坑 6：登录后接口还是 401&quot;">​</a></h2><p><strong>症状</strong>：登录成功了，后续请求 401。</p><p><strong>排查思路</strong>：</p><ol><li><strong>没把 Token 写进 Header</strong>：登录响应里的 <code>data.token</code> 必须设为 <code>Authorization: Bearer &lt;token&gt;</code></li><li><strong>没用同一个 Session</strong>：登录和后续请求要共用一个 <code>requests.Session()</code>，并在其上 <code>headers.update</code></li><li><strong>只塞了写死 token、没真正 login</strong>：testing-online 要先登录激活服务端 session，否则即使用 <code>token-admin-001</code> 也会 401</li><li><strong>后端刚重启</strong>：内存 session 清空，需要重新登录</li></ol><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requests.Session()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> s.post(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{BASE_URL}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/auth/login&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;username&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;炊烟1号&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;password&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin123&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">assert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> r.status_code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">s.headers.update({</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Authorization&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Bearer </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r.json()[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> s.get(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{BASE_URL}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/products&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅</span></span></code></pre></div><h2 id="坑-7-header-写错格式" tabindex="-1">坑 7：Header 写错格式 <a class="header-anchor" href="#坑-7-header-写错格式" aria-label="Permalink to &quot;坑 7：Header 写错格式&quot;">​</a></h2><p><strong>症状</strong>：明明有 token，仍然 401。</p><p><strong>常见错误</strong>：</p><ol><li>写成 <code>Authorization: token-xxx</code>（缺少 <code>Bearer </code> 前缀）</li><li>写成 Cookie：<code>s.cookies.set(&#39;auth_token&#39;, ...)</code> —— <strong>对本项目无效</strong></li><li>从响应里取错字段：应取 <code>resp.json()[&#39;data&#39;][&#39;token&#39;]</code>，不是顶层 <code>token</code></li></ol><p><strong>解决</strong>：登录成功后打印 <code>s.headers.get(&#39;Authorization&#39;)</code>，确认形如 <code>Bearer token-admin-001</code>。</p><h2 id="坑-8-接口断言太脆弱" tabindex="-1">坑 8：接口断言太脆弱 <a class="header-anchor" href="#坑-8-接口断言太脆弱" aria-label="Permalink to &quot;坑 8：接口断言太脆弱&quot;">​</a></h2><p><strong>症状</strong>：测试经常因为「数据变了」而失败。</p><p><strong>原因</strong>：断言了不该断言的——比如断言列表总数是固定值（种子数据会变）、断言某个具体 ID 存在（会被删）。</p><p><strong>解决</strong>：断「结构性」而非「具体值」——<code>total &gt; 0</code> 而非 <code>total == 5</code>，<code>&#39;name&#39; in first</code> 而非 <code>first[&#39;name&#39;] == &#39;iPhone&#39;</code>。</p><h2 id="坑-9-marker-警告" tabindex="-1">坑 9：marker 警告 <a class="header-anchor" href="#坑-9-marker-警告" aria-label="Permalink to &quot;坑 9：marker 警告&quot;">​</a></h2><p><strong>症状</strong>：跑测试冒出 <code>PytestUnknownMarkWarning</code>。</p><p><strong>原因</strong>：用了未注册的自定义 marker（如 <code>@pytest.mark.slow</code>）。</p><p><strong>解决</strong>：在配置里注册（第 25 章），或加 <code>--strict-markers</code> 让拼写错误显形。</p><h2 id="坑-10-测试之间有顺序依赖" tabindex="-1">坑 10：测试之间有顺序依赖 <a class="header-anchor" href="#坑-10-测试之间有顺序依赖" aria-label="Permalink to &quot;坑 10：测试之间有顺序依赖&quot;">​</a></h2><p><strong>症状</strong>：单独跑 <code>pytest -k test_b</code> 失败，全套跑却通过（或反之）。</p><p><strong>原因</strong>：<code>test_b</code> 依赖 <code>test_a</code> 创建的副作用（比如 <code>test_a</code> 创建的订单，<code>test_b</code> 拿来用）。这是<strong>设计错误</strong>——测试必须相互独立。</p><p><strong>解决</strong>：把依赖的数据准备放进 fixture（<code>temp_product</code> 那套「创建→yield→删除」），别让测试间共享状态。用 <code>pytest-randomly</code> 随机顺序能暴露这类问题。</p><h2 id="排查通用清单" tabindex="-1">排查通用清单 <a class="header-anchor" href="#排查通用清单" aria-label="Permalink to &quot;排查通用清单&quot;">​</a></h2><p>遇到测试问题，按这个顺序查：</p><ol><li><strong>看错误信息</strong>：<code>--tb=short -l</code> 显示回溯和局部变量，先读懂再说</li><li><strong>隔离问题</strong>：<code>pytest -k 出错的测试名</code> 单独跑，排除干扰</li><li><strong>看真实响应</strong>：<code>-s</code> 或临时 <code>print(resp.text)</code>，看服务端到底返回了什么</li><li><strong>手动复现</strong>：<code>curl</code> 或 Python REPL 手动发请求，确认是测试代码问题还是服务端问题</li><li><strong>查缓存</strong>：<code>--cache-clear</code> 清状态，<code>__pycache__</code> 清 pyc</li><li><strong>查配置</strong>：<code>--trace-config</code> 看加载了哪些配置和插件</li></ol><blockquote><p><strong>要点：接口测试排错的第一原则——先区分「测试代码错了」还是「服务端错了」。手动 curl 一下就能排除一半可能。</strong></p></blockquote>`,52)])])}const g=i(n,[["render",o]]);export{c as __pageData,g as default};
